script:
(function () {
    var container = root_element.getElementById('customer-readiness-widget');

    container.innerHTML = '<div class="readiness-loading text-muted">' + __('Loading') + '...</div>';

    frappe.xcall('etransactions.etransactions.api.widgets.get_customer_readiness_data')
        .then(function (data) {
            render(data || { total: 0, ready: 0, ready_pct: 0, checks: [], by_group: [] });
        });

    function get_color(pct) {
        if (pct >= 90) return 'var(--green-500, #29cd42)';
        if (pct >= 70) return 'var(--yellow-500, #ecad40)';
        if (pct >= 50) return 'var(--orange-500, #e8891c)';
        return 'var(--red-500, #e24c4c)';
    }

    function build_gauge(check) {
        var pct = check.pct;
        var color = get_color(pct);
        var optional_tag = check.blocking ? '' : ' <em>(' + __('optional') + ')</em>';
        var gauge = document.createElement('div');
        gauge.className = 'readiness-gauge';
        gauge.innerHTML =
            '<div class="gauge-ring-wrapper">' +
                '<svg viewBox="0 0 36 36" class="gauge-ring">' +
                    '<path class="gauge-bg" d="M18 2.0845 a 15.9155 15.9155 0 0 1 0 31.831 a 15.9155 15.9155 0 0 1 0 -31.831" fill="none" stroke-width="3"/>' +
                    '<path class="gauge-fill" d="M18 2.0845 a 15.9155 15.9155 0 0 1 0 31.831 a 15.9155 15.9155 0 0 1 0 -31.831" fill="none" stroke-width="3" stroke-dasharray="' + pct + ', 100" style="stroke: ' + color + '"/>' +
                '</svg>' +
                '<span class="gauge-pct">' + pct + '%</span>' +
            '</div>' +
            '<span class="gauge-label" title="' + frappe.utils.escape_html(__(check.label)) + '">' + frappe.utils.escape_html(__(check.label)) + optional_tag + '</span>' +
            '<span class="gauge-detail">' + check.complete + ' / ' + check.total + '</span>';
        return gauge;
    }

    function build_group_table(by_group) {
        var section = document.createElement('div');
        section.className = 'readiness-by-group';

        var heading = document.createElement('div');
        heading.className = 'readiness-group-heading';
        heading.textContent = __('By Customer Group');
        section.appendChild(heading);

        var table = document.createElement('table');
        table.className = 'readiness-group-table';

        var thead = document.createElement('thead');
        thead.innerHTML =
            '<tr>' +
                '<th>' + __('Group') + '</th>' +
                '<th>' + __('Total') + '</th>' +
                '<th>' + __('Ready') + '</th>' +
                '<th>%</th>' +
            '</tr>';
        table.appendChild(thead);

        var tbody = document.createElement('tbody');
        by_group.forEach(function (g) {
            var color = get_color(g.ready_pct);
            var tr = document.createElement('tr');
            tr.innerHTML =
                '<td>' + frappe.utils.escape_html(g.group) + '</td>' +
                '<td>' + g.total + '</td>' +
                '<td>' + g.ready + '</td>' +
                '<td><span class="group-pct" style="color:' + color + ';font-weight:600">' + g.ready_pct + '%</span></td>';
            tbody.appendChild(tr);
        });
        table.appendChild(tbody);
        section.appendChild(table);
        return section;
    }

    function render(data) {
        container.innerHTML = '';

        var widget = document.createElement('div');
        widget.className = 'readiness-widget';

        var header = document.createElement('div');
        header.className = 'readiness-header';
        header.innerHTML =
            '<span class="readiness-title">' + __('Customer Readiness') + '</span>' +
            '<span class="readiness-summary text-muted">' +
                data.total + ' ' + __('active customers') + ' · ' +
                data.ready + ' ' + __('fully ready') + ' (' + data.ready_pct + '%)' +
            '</span>';
        widget.appendChild(header);

        if (!data.total) {
            var empty = document.createElement('div');
            empty.className = 'readiness-empty text-muted';
            empty.textContent = __('No active customers found.');
            widget.appendChild(empty);
        } else {
            var grid = document.createElement('div');
            grid.className = 'readiness-grid';
            (data.checks || []).forEach(function (check) {
                grid.appendChild(build_gauge(check));
            });
            widget.appendChild(grid);

            if (data.by_group && data.by_group.length) {
                widget.appendChild(build_group_table(data.by_group));
            }
        }

        var footer = document.createElement('div');
        footer.className = 'readiness-footer';
        var link = document.createElement('a');
        link.href = '#';
        link.className = 'readiness-report-link btn btn-xs btn-default';
        link.textContent = __('View full report');
        link.addEventListener('click', function (e) {
            e.preventDefault();
            frappe.set_route('query-report', 'Customer eInvoice Readiness');
        });
        footer.appendChild(link);
        widget.appendChild(footer);

        container.appendChild(widget);
    }
})();

style:
#customer-readiness-widget {
    margin: -7px;

    .readiness-widget {
        padding: var(--padding-md) var(--padding-xl);
        background: var(--fg-color);
        border-radius: var(--border-radius-lg);
        border: 1px solid var(--border-color);
    }

    .readiness-loading,
    .readiness-empty {
        padding: var(--padding-xl);
        text-align: center;
    }

    .readiness-header {
        display: flex;
        align-items: baseline;
        flex-wrap: wrap;
        gap: var(--padding-sm);
        margin-bottom: var(--padding-lg);
    }

    .readiness-title {
        font-size: var(--text-lg);
        font-weight: 600;
        color: var(--heading-color);
    }

    .readiness-summary {
        font-size: var(--text-sm);
    }

    .readiness-grid {
        display: flex;
        flex-wrap: wrap;
        gap: var(--padding-xl);
        justify-content: flex-start;
    }

    .readiness-gauge {
        display: flex;
        flex-direction: column;
        align-items: center;
        width: 88px;
        gap: 4px;
    }

    .gauge-ring-wrapper {
        position: relative;
        width: 64px;
        height: 64px;
        display: flex;
        align-items: center;
        justify-content: center;
    }

    .gauge-ring {
        width: 64px;
        height: 64px;
        transform: rotate(-90deg);
    }

    .gauge-bg { stroke: var(--gray-200, #e8e8e8); }

    .gauge-fill { transition: stroke-dasharray 0.5s ease; }

    .gauge-pct {
        position: absolute;
        font-size: var(--text-sm);
        font-weight: 600;
        color: var(--text-color);
    }

    .gauge-label {
        font-size: var(--text-xs);
        text-align: center;
        color: var(--text-muted);
        max-width: 88px;
        overflow: hidden;
        text-overflow: ellipsis;
        white-space: nowrap;

        em { font-style: normal; opacity: 0.65; }
    }

    .gauge-detail {
        font-size: var(--text-xs);
        color: var(--text-light, var(--text-muted));
    }

    .readiness-by-group {
        margin-top: var(--padding-lg);
        border-top: 1px solid var(--border-color);
        padding-top: var(--padding-md);
    }

    .readiness-group-heading {
        font-size: var(--text-xs);
        font-weight: 600;
        color: var(--text-muted);
        text-transform: uppercase;
        letter-spacing: 0.05em;
        margin-bottom: var(--padding-sm);
    }

    .readiness-group-table {
        width: 100%;
        font-size: var(--text-sm);
        border-collapse: collapse;

        thead th {
            text-align: left;
            padding: var(--padding-xs) var(--padding-sm);
            color: var(--text-muted);
            border-bottom: 1px solid var(--border-color);
            font-weight: 500;
        }

        tbody td {
            padding: var(--padding-xs) var(--padding-sm);
            border-bottom: 1px solid var(--border-color);
        }

        tbody tr:last-child td { border-bottom: none; }
    }

    .readiness-footer {
        margin-top: var(--padding-lg);
        display: flex;
        justify-content: flex-end;
    }

    .readiness-report-link { font-size: var(--text-sm); }
}
